param([Parameter(Mandatory=$true)][ValidateSet('stage','test')][string]$Action)
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-runtime-tail-20260914';$sha='24c4304a16a1665701d05444619d46b832c73e43'
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
$out=Join-Path $repo ('build\current-package-'+$Action+'-r1');$specPath=Join-Path $repo ('build\current-package-'+$Action+'-r1.json')
foreach($p in @($out,$specPath)){if(Test-Path $p){throw ('Existing evidence: '+$p)}}
$spec=[ordered]@{executable='C:\Program Files\Python313\python.exe';working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();model='D:/models/Qwen3.6-35B-A3B';inference_acceptance=$false;purpose='Current24c/42c/4a7/2ee portable package, followed by actual HTTP correctness and transport. Numeric environment options match the qualified q8192 control. Performance and release thresholds remain unchanged; no publication.'}
if($Action -eq 'stage'){
 $command='D:\projects\stage_current_package_r1.py';$spec.arguments=@($command);$spec.model='none; stage verified runtime and CPU preflight';$spec.model_loaded=$false;$timeout=360
}else{
 $command=Join-Path $repo 'scripts\verify_baiying_q8192_http.py';$config=Join-Path $repo 'build\current-package-http-config-r1.json';$spec.config_sha256=(Get-FileHash $config -Algorithm SHA256).Hash.ToLowerInvariant();$spec.arguments=@($command,'--execute','--config',$config,'--out',(Join-Path $repo 'build\current-package-requests-r1'));$timeout=420
}
if($Action -eq 'stage' -and (Get-FileHash $command -Algorithm SHA256).Hash.ToLowerInvariant() -ne '88cdc7ce537e510f72fda4e5a354e092e1c40c3c40bbf3fcacf81edf6dde35e6'){throw 'Stage controller changed'}
$spec.controller_file=$command;$spec.controller_sha256=(Get-FileHash $command -Algorithm SHA256).Hash.ToLowerInvariant()
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
foreach($name in @('product.stdout.jsonl','product.stderr.log')){Get-Content (Join-Path $out $name) -Tail 5}
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw ('HTTP '+$Action+' failed')}
